const {chromium}=require('./browser/node_modules/playwright');
const fs=require('fs');
const base='http://127.0.0.1:4181';const results=[];const bugs=[];const errors=[];
const log=(name,data)=>{results.push({name,data});console.log(name,JSON.stringify(data))};
(async()=>{const browser=await chromium.launch();const ctx=await browser.newContext({viewport:{width:1440,height:1000}});const p=await ctx.newPage();p.on('pageerror',e=>errors.push(e.message));p.on('response',r=>{if(r.status()>=500)errors.push(r.status()+' '+r.url())});
await p.goto(base+'/ro/');await p.waitForSelector('.hero');await p.locator('[data-action=cookies]').click();
const boot=await p.request.get(base+'/api/dracula/bootstrap?lang=ro').then(r=>r.json());log('bootstrap',{demo:boot.demo,languages:boot.languages,categories:boot.categories,products:boot.products.map(x=>({id:x.external_id,name:x.name,categories:x.categories,category:x.category})),pages:boot.pages.map(x=>x.slug)});
await p.screenshot({path:'outputs/dracula-design-office/audit-desktop.png',fullPage:true});
for(const locale of ['ro','en','de']){await p.goto(base+'/'+locale+'/collection');await p.waitForSelector('.product');log('locale-'+locale,{lang:await p.locator('html').getAttribute('lang'),h1:await p.locator('h1').textContent(),filters:await p.locator('.filters button').allTextContents()});for(const cat of boot.categories){await p.locator('[data-filter="'+cat.code+'"]').click();log('filter-'+locale+'-'+cat.code,await p.locator('.product h3').allTextContents())}await p.locator('[data-filter=all]').click();await p.locator('#search').fill('impossible-search-qaaudit');await p.waitForTimeout(150);log('search-empty-'+locale,await p.locator('.product').count());}
for(const width of [390,768]){await p.setViewportSize({width,height:844});await p.goto(base+'/ro/');await p.waitForSelector('.hero');log('viewport-'+width,await p.evaluate(()=>({inner:innerWidth,scroll:document.documentElement.scrollWidth,missingImgAlt:[...document.querySelectorAll('img')].filter(i=>!i.hasAttribute('alt')).length,emptyButtons:[...document.querySelectorAll('button')].filter(i=>!i.textContent.trim()&&!i.getAttribute('aria-label')).length,brokenImages:[...document.images].filter(i=>i.complete&&!i.naturalWidth).map(i=>i.src)})));if(width===390)await p.screenshot({path:'outputs/dracula-design-office/audit-mobile.png',fullPage:true});}
await p.setViewportSize({width:1440,height:1000});
for(const legal of boot.pages){await p.goto(base+'/ro/pages/'+legal.slug);await p.waitForSelector('h1');log('page-'+legal.slug,{h1:await p.locator('h1').textContent(),body:(await p.locator('.legal-body').textContent()).length,draft:await p.locator('.notice').count()});}
log('unauth-admin-api',(await p.request.get(base+'/api/admin/v1/products')).status());log('unauth-profile',(await p.request.get(base+'/api/account/profile')).status());
await p.goto(base+'/ro/account');await p.locator('[name=email]').fill('client@dracula-design.com');await p.locator('[name=password]').fill(process.env.QA_PASSWORD);await p.locator('form button[type=submit]').click();await p.waitForSelector('[data-action=logout]');log('client-login','pass');
const originalCart=await p.request.get(base+'/api/cart?lang=ro').then(r=>r.json());log('cart-before',originalCart.items.length);if(originalCart.items.length)throw Error('Existing client cart; refusing destructive checkout audit');
await p.goto(base+'/ro/collection');await p.waitForSelector('.product');const favorite=p.locator('[data-action=favorite]').first();const before=await favorite.getAttribute('aria-pressed');await favorite.click();await p.waitForTimeout(250);const toggled=await p.locator('[data-action=favorite]').first().getAttribute('aria-pressed');await p.reload();await p.waitForSelector('.product');const persisted=await p.locator('[data-action=favorite]').first().getAttribute('aria-pressed');log('favorites',{before,toggled,persisted});await p.locator('[data-action=favorite]').first().click();await p.waitForTimeout(250);
await p.locator('.product-image').first().click();await p.locator('[data-action=image]').click();log('image-dialog',await p.locator('#image-dialog').isVisible());await p.keyboard.press('Escape');await p.locator('[data-action=add]').first().click();await p.waitForTimeout(300);await p.goto(base+'/ro/bag');await p.waitForSelector('[data-qty]');await p.locator('[data-qty]').fill('2');await p.locator('[data-qty]').press('Tab');await p.waitForTimeout(300);log('cart-qty',await p.locator('[data-qty]').inputValue());await p.locator('[data-qty]').fill('1');await p.locator('[data-qty]').press('Tab');await p.waitForTimeout(300);
await p.goto(base+'/ro/checkout');await p.waitForSelector('[name=first_name]');for(const [k,v] of Object.entries({first_name:'QA',last_name:'AUDIT DESIGN',phone:'0722123456',line1:'TEST AUDIT - fara livrare',city:'Brasov',county:'Brasov',postal_code:'500001',notes:'TEST AUDIT INDEPENDENT DESIGN - fara livrare, fara incasare'}))await p.locator('[name='+k+']').fill(v);await p.locator('[name=accept_terms]').check();await p.screenshot({path:'outputs/dracula-design-office/audit-checkout.png',fullPage:true});
const orderResponse=p.waitForResponse(r=>r.url().includes('/api/orders')&&r.request().method()==='POST');await p.locator('form button[type=submit]').click();const order=await orderResponse;log('checkout-response',{status:order.status(),body:await order.json()});await p.waitForURL('**/confirmation');log('checkout-confirmation',await p.locator('h1').textContent());await p.goto(base+'/ro/account');await p.waitForSelector('[data-action=logout]');log('order-history',await p.locator('.order-card').allTextContents());await p.locator('[data-action=order]').first().click();log('order-detail',await p.locator('.order-info').textContent());await p.keyboard.press('Escape');
const csrf=(await ctx.cookies()).find(c=>c.name==='dracula_csrf')?.value;log('mutation-without-csrf',(await p.request.patch(base+'/api/account/profile',{data:{full_name:'SHOULD NOT APPLY'}})).status());log('stripe-demo-disabled',(await p.request.post(base+'/api/payments/stripe/session',{headers:{'X-CSRF-Token':csrf},data:{}})).status());
await p.goto(base+'/admin/login?ui=classic');await p.locator('input[type=email]').fill('admin@dracula-design.com');await p.locator('input[type=password]').fill(process.env.QA_PASSWORD);await p.locator('[data-testid=login-submit]').click();await p.waitForTimeout(700);for(const path of ['products','categories','orders','customers','legal-pages','translations','inquiries','settings','users']){await p.goto(base+'/admin/'+path+'?ui=classic');await p.waitForTimeout(500);log('admin-'+path,{h1:await p.locator('h1').allTextContents(),text:(await p.locator('body').innerText()).slice(0,600)});if(path==='categories')await p.screenshot({path:'outputs/dracula-design-office/audit-admin.png',fullPage:true});}
log('errors',errors);await browser.close();fs.writeFileSync('work/audit-design-results.json',JSON.stringify({results,bugs,errors},null,2));})().catch(e=>{console.error(e);fs.writeFileSync('work/audit-design-results.json',JSON.stringify({results,bugs,errors,fatal:e.message},null,2));process.exit(1)});
